entries[372418] = { ["name"] = "Fated Power: Protoform Barrier", ["text"] = "Instant\nEmpowers the caster, inflicting 3 Cosmic damage to all players every 3 sec.\n\nUpon removal this barrier manifests as one attackable enemy, casting a shared 1600 absorb shield with all other enemies for 15 sec. A second unit manifests that also can be healed to reduce the shared shield.\n\nUpon expiration the barrier explodes, inflicting 50 Cosmic damage and an additional 5 Cosmic damage every 1 sec. to all players for 8 sec.\n\nIf broken this effect backfires, inflicting all damage done to each enemy during the barrier as Cosmic damage, and additionally grants all players up to 20% increased damage done, 20% healing done, 30% total health, and 20% increased absorbs done for 40 sec." }
entries[372419] = { ["name"] = "Fated Power: Reconfiguration Emitter", ["text"] = "Instant\nManifests an attackable enemy which continuously casts. This enemy remains immune to damage until the first successful cast or interrupt. Successful casts inflict 30 Cosmic damage to all players. Every 5 sec. the emitter gains 0 % increased damage done. This effect stacks.\n\nWhen successfully interrupted the emitter radiates, inflicting 5 Cosmic damage to all players.\n\nUpon defeat this enemy infuses all players with power based on the energy level of the emitter, increasing mastery by up to 10 , critical strike chance by up to 10 %, versatility by up to 10 %, and avoidance by up to 9 ." }
